func TestTmpBindMap(t *testing.T) {
	e := New()
	req := httptest.NewRequest(http.MethodGet, "/?tag=a&tag=b", nil)
	rec := httptest.NewRecorder()
	c := e.NewContext(req, rec)
	m := map[string][]string{}
	if err := c.Bind(&m); err != nil {
		t.Fatal(err)
	}
	if len(m["tag"]) != 2 || m["tag"][0] != "a" || m["tag"][1] != "b" {
		t.Fatalf("got %#v", m)
