	mi := map[string]interface{}{}
	if err := c.Bind(&mi); err != nil {
		t.Fatal(err)
	}
	if v, ok := mi["tag"].([]string); !ok || len(v) != 2 {
		t.Fatalf("got %#v", mi)
	}
	ms := map[string]string{}
	if err := c.Bind(&ms); err != nil {
		t.Fatal(err)
	}
	if ms["tag"] != "a" {
